const MAGAHI_STATS=[{label:"Speakers",value:"~13 Million"},{label:"Language Family",value:"Indo-Aryan"},{label:"Script",value:"Devanagari / Kaithi"},{label:"Primary Region",value:"Bihar & Jharkhand"}],MAGAHI_GREETING={devanagari:"प्रणाम",transliteration:"Praṇām",meaning:"A respectful greeting used across the Magahi-speaking region, roughly equivalent to 'greetings' or 'I bow to you' — used for both hello and goodbye, especially toward elders.",folkVariant:{devanagari:"जोहार",transliteration:"Johār",meaning:"An older, more rural and community-rooted greeting still heard in villages across the Magadha region, historically used as a mark of respect between community members."},note:"Magahi does not have a browser-supported text-to-speech voice, so pronunciation below is played using the closest available Hindi (Devanagari-script) voice as an approximation — not a native Magahi recording. Word stress and vowel length in actual Magahi speech can differ from this playback."},MAGAHI_WORDS=[{devanagari:"पानी",translit:"Pānī",meaning:"Water",note:"Shared with Hindi; pronounced with a softer terminal vowel in everyday Magahi speech."},{devanagari:"नीक",translit:"Nīk",meaning:"Good / Nice",note:"A distinctly Magahi word — unlike Hindi's 'accha', 'neek' is one of the most recognizable Magahi-specific terms."},{devanagari:"घर",translit:"Ghar",meaning:"House / Home",note:"Common Indo-Aryan root shared across most regional languages of the Gangetic plain."},{devanagari:"माय",translit:"Māy",meaning:"Mother",note:"A regional variant distinct from standard Hindi 'maa', reflecting Magahi's own phonetic patterns."},{devanagari:"बाबू",translit:"Bābū",meaning:"Father",note:"Widely used across Bihar's languages, also used respectfully to address elder men."},{devanagari:"किंगे",translit:"Kinge",meaning:"How",note:"A Magahi-specific question word, differing noticeably from Hindi's 'kaise'."},{devanagari:"खाना",translit:"Khānā",meaning:"Food / To eat",note:"Shared root with Hindi and other Indo-Aryan languages of the region."},{devanagari:"दिन",translit:"Din",meaning:"Day",note:"Common Indo-Aryan vocabulary, largely unchanged from Sanskrit 'dina'."},{devanagari:"इनका",translit:"Inkā",meaning:"This person's / theirs (near)",note:"Magahi pronoun form, structurally distinct from standard Hindi possessive forms."},{devanagari:"जल्दी",translit:"Jaldī",meaning:"Quickly",note:"Common across neighboring Indo-Aryan languages, used identically in everyday Magahi speech."}],MAGAHI_SCRIPT={intro:"Magahi is written today primarily in the Devanagari script, the same script used for Hindi and Sanskrit. Historically, it was also written in the Kaithi script — a cursive script once widely used across Bihar for administrative and everyday writing before Devanagari became standard in the 20th century.",facts:[{title:"Devanagari Today",detail:"Modern books, newspapers, and digital content in Magahi are printed almost exclusively in Devanagari, aiding mutual readability with Hindi speakers."},{title:"Kaithi Heritage",detail:"Kaithi script manuscripts and land records from the 19th and early 20th centuries preserve some of the oldest surviving written Magahi documents."},{title:"Phonetic Features",detail:"Magahi retains certain vowel and consonant patterns closer to Magadhi Prakrit than standard Hindi, particularly in verb conjugation and pronoun forms."}]},MAGAHI_CLASSIFICATION={family:"Indo-European → Indo-Iranian → Indo-Aryan → Eastern Zone",siblings:["Bhojpuri","Maithili","Angika"],note:"Magahi belongs to the Eastern Indo-Aryan group known as the 'Bihari languages', which descend from Magadhi Prakrit and Apabhramsha, the vernacular tongues spoken in the ancient Magadha region during and after the time of the Buddha and Mahavira."},MAGAHI_REGION={intro:"Magahi is spoken primarily across south-central Bihar and neighboring parts of Jharkhand, roughly corresponding to the historical territory of the ancient Magadha kingdom.",districts:["Patna","Gaya","Nawada","Nalanda","Jehanabad","Aurangabad","Sheikhpura","Lakhisarai","Hazaribagh (Jharkhand)"]},MAGAHI_CULTURE=[{title:"Oral Folk Tradition",desc:"Magahi has a rich tradition of orally transmitted folk songs, proverbs, and ballads performed at weddings, harvest festivals, and seasonal celebrations across the Magadha region."},{title:"Magahi Cinema",desc:"A small but active regional film industry produces Magahi-language films and music, helping sustain everyday spoken use of the language among younger generations."},{title:"Link to Ancient Magadha",desc:"The language's name directly derives from Magadha, the ancient kingdom that gave rise to the Maurya and Gupta Empires and was closely associated with the early spread of Buddhism and Jainism."},{title:"Scheduled Language Recognition Movement",desc:"Magahi speakers and linguists have long advocated for the language's inclusion in the Eighth Schedule of the Indian Constitution, which would grant it official recognition alongside languages like Hindi, Maithili, and Bhojpuri."}],MAGAHI_REFERENCES=[{text:"Grierson, George A. Linguistic Survey of India, Vol. V: Bihari and Oriya Languages. 1903.",url:"https://archive.org/"},{text:"Verma, Shivendra K. 'Magahi' in The Indo-Aryan Languages, Routledge, 2003.",url:"https://www.routledge.com/"},{text:"Census of India — Statement of Language and Mother Tongue Strength.",url:"https://censusindia.gov.in/"},{text:"People's Linguistic Survey of India (PLSI) — Bihari Languages Volume.",url:"https://peopleslinguisticsurvey.org/"}];